#!/usr/bin/env python3
"""Pydantic models for Claude transcript JSONL parsing."""

from datetime import datetime
from typing import Any, Dict, List, Optional, Union
from pydantic import BaseModel, Field


class UsageMetadata(BaseModel):
    """Usage metadata from Claude responses."""
    input_tokens: int
    cache_creation_input_tokens: Optional[int] = None
    cache_read_input_tokens: Optional[int] = None
    output_tokens: int
    service_tier: Optional[str] = None


class ThinkingContent(BaseModel):
    """Thinking content block."""
    type: str = Field(..., description="Content type, should be 'thinking'")
    thinking: str = Field(..., description="The thinking content")
    signature: Optional[str] = None


class TextContent(BaseModel):
    """Text content block."""
    type: str = Field(..., description="Content type, should be 'text'")
    text: str = Field(..., description="The text content")


class ToolUseContent(BaseModel):
    """Tool use content block."""
    type: str = Field(..., description="Content type, should be 'tool_use'")
    id: str = Field(..., description="Tool use ID")
    name: str = Field(..., description="Tool name")
    input: Dict[str, Any] = Field(..., description="Tool input parameters")


class ToolResultContent(BaseModel):
    """Tool result content block."""
    type: str = Field(..., description="Content type, should be 'tool_result'")
    tool_use_id: str = Field(..., description="ID of the tool use this result belongs to")
    content: str = Field(..., description="Result content")
    is_error: Optional[bool] = None


# Union type for all content blocks
ContentItem = Union[ThinkingContent, TextContent, ToolUseContent, ToolResultContent]


class BaseMessage(BaseModel):
    """Base class for message content."""
    role: str = Field(..., description="Message role (user, assistant, system)")
    content: Union[str, List[ContentItem]] = Field(..., description="Message content")


class UserMessage(BaseMessage):
    """User message structure."""
    role: str = Field(default="user", description="Always 'user' for user messages")


class AssistantMessage(BaseMessage):
    """Assistant message structure."""
    id: str = Field(..., description="Message ID")
    type: str = Field(..., description="Message type")
    role: str = Field(default="assistant", description="Always 'assistant'")
    model: str = Field(..., description="Model used")
    stop_reason: Optional[str] = None
    stop_sequence: Optional[str] = None
    usage: Optional[UsageMetadata] = None


class ToolUseResultData(BaseModel):
    """Tool use result data structure."""
    oldTodos: Optional[List[Dict[str, Any]]] = None
    newTodos: Optional[List[Dict[str, Any]]] = None
    type: Optional[str] = None
    file: Optional[Dict[str, Any]] = None


class BaseTranscriptEntry(BaseModel):
    """Base class for all transcript entries."""
    parentUuid: Optional[str] = None
    isSidechain: bool = False
    userType: str = "external"
    cwd: Optional[str] = None
    sessionId: Optional[str] = None
    version: Optional[str] = None
    type: str = Field(..., description="Entry type")
    uuid: str = Field(..., description="Unique identifier")
    timestamp: str = Field(..., description="ISO timestamp")


class UserTranscriptEntry(BaseTranscriptEntry):
    """User transcript entry."""
    type: str = Field(default="user", description="Always 'user'")
    message: UserMessage = Field(..., description="User message")
    toolUseResult: Optional[ToolUseResultData] = None


class AssistantTranscriptEntry(BaseTranscriptEntry):
    """Assistant transcript entry."""
    type: str = Field(default="assistant", description="Always 'assistant'")
    message: AssistantMessage = Field(..., description="Assistant message")
    requestId: Optional[str] = None


class SummaryTranscriptEntry(BaseModel):
    """Summary transcript entry."""
    type: str = Field(default="summary", description="Always 'summary'")
    summary: str = Field(..., description="Session summary")
    leafUuid: str = Field(..., description="UUID of the leaf message")


# Union type for all transcript entries
TranscriptEntry = Union[UserTranscriptEntry, AssistantTranscriptEntry, SummaryTranscriptEntry]


def parse_content_item(item_dict: Dict[str, Any]) -> ContentItem:
    """Parse a content item dictionary into the appropriate Pydantic model."""
    content_type = item_dict.get("type", "")

    if content_type == "thinking":
        return ThinkingContent(**item_dict)
    elif content_type == "text":
        return TextContent(**item_dict)
    elif content_type == "tool_use":
        return ToolUseContent(**item_dict)
    elif content_type == "tool_result":
        return ToolResultContent(**item_dict)
    else:
        # Fallback to text content for unknown types
        return TextContent(type="text", text=str(item_dict))


def parse_message_content(content: Union[str, List[Dict[str, Any]]]) -> Union[str, List[ContentItem]]:
    """Parse message content into appropriate structure."""
    if isinstance(content, str):
        return content
    elif isinstance(content, list):
        return [parse_content_item(item) for item in content]
    else:
        return str(content)


def parse_transcript_entry(entry_dict: Dict[str, Any]) -> TranscriptEntry:
    """Parse a transcript entry dictionary into the appropriate Pydantic model."""
    entry_type = entry_dict.get("type", "")

    if entry_type == "summary":
        return SummaryTranscriptEntry(**entry_dict)
    elif entry_type == "user":
        # Parse message content
        message_data = entry_dict.get("message", {})
        if "content" in message_data:
            message_data["content"] = parse_message_content(message_data["content"])

        # Create a copy of entry_dict and update the message
        entry_copy = entry_dict.copy()
        entry_copy["message"] = UserMessage(**message_data)
        return UserTranscriptEntry(**entry_copy)
    elif entry_type == "assistant":
        # Parse message content
        message_data = entry_dict.get("message", {})
        if "content" in message_data:
            message_data["content"] = parse_message_content(message_data["content"])

        # Create a copy of entry_dict and update the message
        entry_copy = entry_dict.copy()
        entry_copy["message"] = AssistantMessage(**message_data)
        return AssistantTranscriptEntry(**entry_copy)
    else:
        raise ValueError(f"Unknown transcript entry type: {entry_type}")


def try_parse_transcript_entry(entry_dict: Dict[str, Any]) -> Optional[TranscriptEntry]:
    """Try to parse a transcript entry, returning None if parsing fails."""
    try:
        return parse_transcript_entry(entry_dict)
    except Exception:
        return None

