        raise ValueError(f"Unknown transcript entry type: {entry_type}")


def try_parse_transcript_entry(entry_dict: Dict[str, Any]) -> Optional[TranscriptEntry]:
    """Try to parse a transcript entry, returning None if parsing fails."""
    try:
        return parse_transcript_entry(entry_dict)
    except Exception:
        return None


def parse_transcript_entry_with_fallback(entry_dict: Dict[str, Any]) -> Optional[TranscriptEntry]:
    """
    Try to parse a transcript entry against different Pydantic models.

    This function attempts to parse the entry using each model type in order:
    1. Summary entries
    2. User entries  
    3. Assistant entries

    If none match, it raises an error describing what was tried.

    Args:
        entry_dict: Dictionary parsed from JSON

    Returns:
        The appropriate TranscriptEntry subclass, or None if parsing fails

    Raises:
        ValueError: If the entry doesn't match any known transcript entry type
    """
    entry_type = entry_dict.get("type", "unknown")

    # Try parsing as each type explicitly
    parsing_errors = []

    # Try summary first (simplest structure)
    if entry_type == "summary" or not entry_type:
        try:
            return SummaryTranscriptEntry.model_validate(entry_dict)
        except Exception as e:
            parsing_errors.append(f"SummaryTranscriptEntry: {str(e)}")

    # Try user entry
    if entry_type == "user" or not entry_type:
        try:
            return UserTranscriptEntry.model_validate(entry_dict)
        except Exception as e:
            parsing_errors.append(f"UserTranscriptEntry: {str(e)}")

    # Try assistant entry
    if entry_type == "assistant" or not entry_type:
        try:
            return AssistantTranscriptEntry.model_validate(entry_dict)
        except Exception as e:
            parsing_errors.append(f"AssistantTranscriptEntry: {str(e)}")

    # If we get here, none of the models worked
    error_summary = "\n".join(f"  - {error}" for error in parsing_errors)
    raise ValueError(
        f"Could not parse transcript entry with type '{entry_type}'. "
        f"Tried the following models:\n{error_summary}"
    )

