"""Quick test to verify thinking token parsing works without Pydantic errors."""

import json
from claude_code_log.models import parse_transcript_entry

# Sample JSON with thinking content (based on user's example)
sample_json = {
    "parentUuid": "9524e747-14cb-4e66-a91f-f0f0ef1147fb",
    "isSidechain": False,
    "userType": "external",
    "cwd": "/Users/dain/workspace/claude-code-log",
    "sessionId": "4f600503-a7d7-4165-aa44-4ba4c937d5ce",
    "version": "1.0.24",
    "message": {
        "id": "msg_014UkiCvABoncgruUvEAEQe7",
        "type": "message",
        "role": "assistant",
        "model": "claude-sonnet-4-20250514",
        "content": [
            {
                "type": "thinking",
                "thinking": "The user wants me to help with something...",
                "signature": "EvMHCkYIBBgCKkAXXD4jxgNKoYEt2Ecpl0kXbLhg7CNHHJ8+"
            },
            {
                "type": "text",
                "text": "I can help you with that task."
            }
        ],
        "stop_reason": None,
        "stop_sequence": None,
        "usage": {
            "input_tokens": 10,
            "cache_creation_input_tokens": 14721,
            "cache_read_input_tokens": 0,
            "output_tokens": 2,
            "service_tier": "standard"
        }
    },
    "requestId": "req_011CQ85AD7aAtqXm6qPYYSjN",
    "type": "assistant",
    "uuid": "3bd90a6b-6f6c-4861-af38-516bcd031f56",
    "timestamp": "2025-06-14T11:57:19.698Z"
}

def test_thinking_parsing():
    """Test that thinking content parses without validation errors."""
    try:
        entry = parse_transcript_entry(sample_json)
        print(f"✅ Successfully parsed entry: {type(entry).__name__}")

        # Check that content was parsed correctly
        content = entry.message.content
        print(f"   Content items: {len(content)}")

        for i, item in enumerate(content):
            print(f"   [{i}] {type(item).__name__}: {item.type}")
            if hasattr(item, 'thinking'):
                print(f"       Thinking preview: {item.thinking[:50]}...")
            elif hasattr(item, 'text'):
                print(f"       Text: {item.text}")

        # Check usage metadata
        if hasattr(entry.message, 'usage') and entry.message.usage:
            usage = entry.message.usage
            print(f"   Usage: {usage.input_tokens} in, {usage.output_tokens} out")

        return True

    except Exception as e:
        print(f"❌ Parsing failed: {e}")
        return False

if __name__ == "__main__":
    success = test_thinking_parsing()
    if success:
        print("\n🎉 Thinking token parsing works correctly!")
    else:
        print("\n💥 Thinking token parsing failed!")

